mapper.select:
SELECT t1.id, t1.key_name, t1.secret, t1.vendor_config_id, t2.vendor_name, t2.vendor_code, t1.rate_limit_rpm, t1.rate_limit_tpd, t1.max_tokens_per_day, t1.used_tokens, t1.total_cost, t1.expires_at, t1.status, t1.remark, t1.create_time FROM sys_llm_api_key_config t1 LEFT JOIN sys_llm_vendor_config t2 ON t1.vendor_config_id = t2.id AND t2.is_deleted = 0
t1.is_deleted = 0
AND ( t1.key_name LIKE '%' || #{queryParams.keywords} || '%' )
AND t1.vendor_config_id = #{queryParams.vendorConfigId}
AND t1.status = #{queryParams.status}
ORDER BY t1.create_time DESC
